from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    results = []
    cache = OrderedDict()  # key -> (value, write_time)

    def purge_expired(current_t):
        # remove all expired entries
        expired_keys = [k for k, (v, wt) in cache.items() if current_t >= wt + ttl]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        kind = op[0]
        t = op[1]
        if kind == 'get':
            key = op[2]
            if key in cache:
                value, wt = cache[key]
                if t >= wt + ttl:
                    # expired
                    del cache[key]
                    results.append(-1)
                else:
                    cache.move_to_end(key)
                    results.append(value)
            else:
                results.append(-1)
        elif kind == 'put':
            key = op[2]
            value = op[3]
            if key in cache:
                old_value, wt = cache[key]
                if t >= wt + ttl:
                    # expired, remove it first
                    del cache[key]
                else:
                    # update existing, refresh time and value, move to end
                    cache[key] = (value, t)
                    cache.move_to_end(key)
                    continue

            # key not present (either never existed or just expired)
            purge_expired(t)
            if key in cache:
                # shouldn't normally happen after purge, but just in case
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    # evict least recently used
                    cache.popitem(last=False)
                cache[key] = (value, t)
        else:
            raise ValueError("Unknown operation type: " + str(kind))

    return results

